export function translateAuth(language: LanguageCode, key: AuthTextKey) {
  return authText[language][key]
}

export function translateAuthError(language: LanguageCode, message: string) {
  if (/invalid login credentials|invalid email or password/i.test(message)) return translateAuth(language, 'invalidCredentials')
  if (/email not confirmed|email confirmation required/i.test(message)) return translateAuth(language, 'emailNotConfirmed')
  if (/user already registered|already registered/i.test(message)) return translateAuth(language, 'accountExists')
  return message || translateAuth(language, 'genericError')
}

