export function formatFoodNumber(value: number, language: LanguageCode, decimals = 1) {
  return new Intl.NumberFormat(language === 'sr' ? 'sr-Latn' : language, { maximumFractionDigits: decimals, minimumFractionDigits: decimals }).format(value)
}

export function formatFoodAmount(value: number, language: LanguageCode) {
  return new Intl.NumberFormat(language === 'sr' ? 'sr-Latn' : language, { maximumFractionDigits: 2 }).format(value)
}

export function formatFoodUnit(unit: 'g' | 'ml' | 'piece' | 'serving' | undefined, language: LanguageCode) {
  return foodLanguageText[language].units[unit ?? 'g']
}

export function foodNutritionLabel(key: NutritionKey, language: LanguageCode) {
  return foodLanguageText[language].labels[key]
}

export function formatFoodNutrition(nutrition: FoodNutrition, language: LanguageCode) {
  const text = foodLanguageText[language]
  return `${text.labels.calories} ${formatFoodNumber(nutrition.calories, language, 0)} kcal | ${text.labels.protein} ${formatFoodNumber(nutrition.protein, language)} ${text.units.g} | ${text.labels.carbs} ${formatFoodNumber(nutrition.carbs, language)} ${text.units.g} | ${text.labels.fats} ${formatFoodNumber(nutrition.fats, language)} ${text.units.g}`
}

export function formatCompactFoodNutrition(nutrition: FoodNutrition, language: LanguageCode) {
  const text = foodLanguageText[language]
  return (['calories', 'protein', 'carbs', 'fats'] as const).map(key =>
    `${text.shortLabels[key]} ${formatFoodNumber(nutrition[key], language, key === 'calories' ? 0 : 1)}${key === 'calories' ? ' kcal' : ` ${text.units.g}`}`
  )
}

