export function translateFoodName(food: { id: string; name: string; user: boolean }, language: LanguageCode) {
  if (food.user) return language === 'sr' ? transliterateSerbianLatin(food.name) : food.name
  const systemEntry = (systemFoodTranslations as Record<string, { source: string; names: Partial<Record<LanguageCode, string>> }>)[food.id]
  if (systemEntry && food.name.trim() === systemEntry.source && systemEntry.names[language]) return systemEntry.names[language]!
  const entry = foodNames[food.id]
  if (entry && food.name.trim() === entry.source && entry.names[language]) return entry.names[language]!
  if (language === 'en') return commonFoodEnglish[normalizeFoodName(food.name)] ?? food.name
  if (language === 'sr') return transliterateSerbianLatin(food.name)
  return food.name
}
